(() => {
  'use strict';
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const court='https://efamily.scourt.go.kr/cs/CsBltnWrtList.do?bltnbordId=0000010';
  function render(n){
    if(n.candidate_reports)return renderCandidates(n);
    const selected=n.characters||[],nameChars=selected.filter(h=>h.kind==='name');
    const hero=`<header class="naming-hero"><span>이름에 담는 첫 마음</span><h3>${esc(n.display_name)}</h3><p class="naming-hanja-line">${esc(n.full_hanja||'한자마다 담을 뜻을 골라봐요')}</p><small>${esc(n.preference_label)}</small></header>`;
    const characters=selected.length?`<section class="report-section"><h3>한 글자씩, 마음을 담아 읽어봐요.</h3><div class="hanja-name-grid naming-characters">${selected.map(h=>`<article class="${h.kind==='surname'?'surname-character':''}"><span class="character-position">${esc(h.position)}</span><b>${esc(h.character)}</b><strong>${esc(h.syllable)}</strong><span>${esc(h.meaning||'한국어 뜻 확인 필요')}</span><p>${esc(h.interpretation||h.wish)}</p>${h.good_for?`<p class="character-good-for"><strong>이 뜻을 담고 싶다면</strong>${esc(h.good_for)}</p>`:''}${h.consideration?`<details class="character-consideration"><summary>함께 생각할 점</summary><p>${esc(h.consideration)}</p></details>`:''}<small class="registry-status ${h.registry.status==='listed'?'confirmed':''}">${esc(h.registry.label)}</small>${h.registry.checked_at?`<small>조회일 ${esc(h.registry.checked_at)}</small>`:''}${h.dictionary_reading_matches===false?'<small>일반 사전 독음은 다를 수 있어 공식 독음 확인을 함께 봐요.</small>':''}</article>`).join('')}</div></section>`:'<div class="missing-analysis"><h4>이름 소리는 정했으니, 담을 뜻을 골라볼까요?</h4><p>아래 한자 조합의 뜻을 비교하고 선택할 수 있어요. 한글 이름을 그대로 사용해도 됩니다.</p></div>';
    const checks=`<section class="naming-checks" aria-label="선택한 이름 확인 결과">${n.checks.map(c=>`<div><strong>${esc(c.label)}</strong><span>${esc(c.status)}</span><p>${esc(c.text)}</p></div>`).join('')}</section>`;
    const chapters=n.chapters.map(c=>`<section class="report-section naming-story" id="naming-${esc(c.topic)}"><h3>${esc(c.title)}</h3>${c.paragraphs.map(p=>`<p>${esc(p)}</p>`).join('')}${c.topic==='birth'&&n.birth.available?`<div class="naming-birth-summary"><span>일주 <b>${esc(n.birth.day_pillar)}</b></span><span>절기 월 <b>${esc(n.birth.season)}</b></span><span>${n.birth.hour_known?'시간까지 확인':'출생 시간 미입력'}</span></div>`:''}</section>`).join('');
    const recs=`<section class="report-section naming-recommendations"><h3>같은 소리, 다른 뜻의 한자 조합</h3><p class="report-description">${esc(n.recommendation_note)}</p><div class="naming-candidates">${n.recommendations.map((r,i)=>`<article class="naming-candidate"><div class="candidate-heading"><span>${i===0?'먼저 비교할 조합':'함께 비교할 조합'}</span><b>${esc(r.name_hanja)}</b><small>${esc(r.name)}</small></div><p class="candidate-meanings">${r.characters.map(h=>esc(h.character)+' · '+esc(h.meaning)).join('<br>')}</p><p>${esc(r.reason)}</p>${r.comparison?`<div class="candidate-comparison"><strong>현재 이름과 달라지는 점</strong><p>${esc(r.comparison)}</p></div>`:''}<details><summary>이 조합에 담을 뜻 읽기</summary><p>${esc(r.story)}</p>${(r.explanation||[]).map(p=>`<p>${esc(p)}</p>`).join('')}</details><span class="candidate-verification">글자·독음 공식 조회 확인</span><button type="button" data-naming-choice="${esc(r.name_hanja)}">이 조합으로 선택하기 →</button></article>`).join('')}</div></section>`;
    return `<div class="naming-report">${hero}${characters}${checks}${chapters}${recs}<details class="method-detail naming-method"><summary>추천 기준과 확인 범위 보기 <span>+</span></summary><p>${esc(n.scope)}</p><p>추천은 검토된 글자의 사전 뜻과 가족이 선택한 바람을 기준으로 합니다. 다른 한자 조합의 추천 순서에 사주 길흉 점수나 운세 확률은 사용하지 않아요.</p><p>인명용 글자와 독음은 ${esc(n.registry_checked_at||'미조회')} 기준으로 수록한 공식 조회 자료로 확인했어요. 성의 한자는 가족이 사용하는 표기를 선택해 주세요.</p><a href="${court}" target="_blank" rel="noopener noreferrer">대법원 인명용 한자에서 최신 정보 확인하기 ↗</a><p><a href="./method.html#naming" target="_blank" rel="noopener noreferrer">이름 상담의 자료와 해석 기준 ↗</a></p></details></div>`;
  }
  function renderCandidates(n){
    const statuses={recommend:'추천 후보',consider:'조건을 보고 비교',not_recommended:'이번 기준에서는 추천 보류',needs_verification:'자료 확인 필요'};
    const comparison=n.comparison?`<section class="report-section naming-comparison"><h3>왜 이 이름들을 먼저 비교할까요?</h3>${n.comparison.paragraphs.map(p=>`<p>${esc(p)}</p>`).join('')}<div class="naming-choice-overview">${n.candidate_reports.map(p=>`<article><h4>${esc(p.display_name)}</h4><strong>${p.recommended_rank?'먼저 비교 · '+p.recommended_rank+'순위':esc(statuses[p.status]||'확인 중')}</strong><p>${esc(p.comparison_reason)}</p><p class="candidate-comparison"><b>함께 볼 점</b><br>${esc(p.comparison_concern)}</p></article>`).join('')}</div></section>`:'<p class="chapter-body" role="status">확인한 글자와 독음을 바탕으로 이름별 해설과 비교 추천을 작성하고 있어요.</p>';
    const tabs=`<nav class="naming-candidate-tabs" aria-label="이름별 자세한 상담">${n.candidate_reports.map((p,i)=>`<button type="button" data-name-detail="name-detail-${i}">${esc(p.display_name)}</button>`).join('')}</nav>`;
    const birth=n.birth?`<p class="birth-frame">공통 출생 정보 · ${esc(n.birth.profile.birth_date)}${n.birth.profile.birth_time?' · '+esc(n.birth.profile.birth_time):' · 출생 시간 미입력'} · ${esc(n.birth.profile.city)}</p>`:'<p class="birth-frame">생일이 없어 이름의 소리와 한자 뜻을 비교해요.</p>';
    const candidates=n.candidate_reports.map((p,i)=>`<details class="reading-chapter reading-fold name-candidate-report" id="name-detail-${i}" ${i===0?'open':''}><summary><span class="report-overline">${esc(p.display_name)} · ${esc(statuses[p.status]||'해설 작성 중')}</span><h3>${esc(p.title||p.display_name+'의 이름 상담')}</h3><span class="fold-mark" aria-hidden="true">+</span></summary><div class="chapter-content">${p.verdict?`<p class="chapter-body">${esc(p.verdict)}</p>`:''}${p.concerns?.length?`<div class="candidate-comparison"><h4>좋은 뜻과 함께 살펴볼 점</h4>${p.concerns.map(c=>`<p>${esc(c)}</p>`).join('')}</div>`:''}${p.chapters.map(c=>`<section class="naming-story"><h4>${esc(c.title)}</h4>${c.paragraphs.map(text=>`<p class="chapter-body">${esc(text)}</p>`).join('')}</section>`).join('')}${p.analysis_pending?`<div class="naming-candidates">${p.combinations.map(c=>`<article class="naming-candidate"><b class="naming-hanja-line">${esc(c.name_hanja)}</b>${c.characters.map(h=>`<p>${esc(h.character)}(${esc(h.syllable)}) · ${esc(h.meaning||'뜻 확인 필요')}<br><small>${esc(h.registry.label)}</small></p>`).join('')}</article>`).join('')||'<p>확인 가능한 한자 후보를 살펴보고 있어요.</p>'}</div>`:`<h4 class="cycle-heading">${esc(p.name)}에 담을 한자 조합</h4><div class="naming-candidates">${p.recommendations.map(r=>`<article class="naming-candidate"><div class="candidate-heading"><span>${r.selected?'입력한 한자 조합':'뜻을 비교할 조합'}</span><b>${esc(r.full_hanja||r.name_hanja)}</b><small>${esc(p.display_name)}</small></div>${r.characters.map(h=>`<p class="candidate-meanings">${esc(h.character)} · ${esc(h.syllable)} · ${esc(h.meaning||'뜻 확인 필요')}<br><small>${esc(h.registry.label)}</small></p>`).join('')}<p>${esc(r.reason)}</p><p>${esc(r.story)}</p>${r.explanation.map(x=>`<p>${esc(x)}</p>`).join('')}<div class="candidate-comparison"><strong>이 조합에서 생각할 점</strong><p>${esc(r.comparison)}</p></div>${r.selectable?`<button type="button" data-naming-choice="${esc(r.name_hanja)}" data-naming-name="${esc(p.name)}">${esc(p.name)} · 이 한자로 선택하기 →</button>`:'<p class="candidate-verification">뜻·독음 추가 확인 후 선택할 수 있어요.</p>'}</article>`).join('')||'<p class="chapter-body">검토된 뜻과 독음을 갖춘 한자 조합이 없어 추천을 보류했어요. 한글 이름 자체가 나쁘다는 뜻은 아니에요.</p>'}</div>`}</div></details>`).join('');
    const surname=n.surname_characters?.length?`<p class="birth-frame">가족에게서 이어받은 성 · ${n.surname_characters.map(h=>esc(h.character)+' ('+esc(h.syllable)+') · '+esc(h.meaning||'뜻 확인 필요')).join(' · ')}</p>`:'';
    const birthStory=n.birth_reading?`<details class="reading-chapter reading-fold"><summary><span class="report-overline">모든 후보가 함께 참고할 아이의 사주</span><h3>${esc(n.birth_reading.chapters[0].title)}</h3><span class="fold-mark" aria-hidden="true">+</span></summary><div class="chapter-content">${n.birth_reading.chapters[0].paragraphs.map(p=>`<p class="chapter-body">${esc(p)}</p>`).join('')}<p class="report-footnote">이 사주는 모든 이름 후보에 공통으로 적용돼요. 한자 자체의 오행·획수 적합도는 현재 판정하지 않아요.</p></div></details>`:'';
    return `<div class="naming-report">${birth}${surname}${comparison}${birthStory}${tabs}${candidates}<details class="method-detail naming-method"><summary>추천 기준과 확인 범위 보기 <span>+</span></summary><p>${esc(n.scope)}</p><p>인명용 글자·독음은 ${esc(n.registry_checked_at||'미조회')}에 수록한 공식 조회 자료 기준이에요. 사전 뜻과 가족의 바람을 비교하며, 한자 자체의 사주 보완 효과를 확정하지 않아요.</p><a href="${court}" target="_blank" rel="noopener noreferrer">공식 인명용 한자 정보 확인하기 ↗</a></details></div>`;
  }
  function mount(root,onChoice){
    root.querySelectorAll('[data-naming-choice]').forEach(button=>button.addEventListener('click',()=>onChoice(button.dataset.namingName?{name:button.dataset.namingName,name_hanja:button.dataset.namingChoice}:button.dataset.namingChoice)));
    root.querySelectorAll('[data-name-detail]').forEach(button=>button.addEventListener('click',()=>{const detail=root.querySelector('#'+button.dataset.nameDetail);detail.open=true;detail.scrollIntoView({block:'start',behavior:'auto'});}));
  }
  window.MoaNaming={render,mount};
})();
